def preflight_check(system):
    findings = []
    if not system.data_is_versioned:
        findings.append("data is unversioned -- past runs unreproducible")
    if system.training_and_serving_feature_code_differ:
        findings.append("training-serving skew risk -- no shared feature definition")
    if not system.has_validation_gate:
        findings.append("no automated data validation gate before training")
    if system.deployment_is_manual:
        findings.append("training/deployment still manually executed")
    if system.deployment_strategy == "all_or_nothing":
        findings.append("no canary/shadow/blue-green safety net")
    if not system.monitors_concept_drift:
        findings.append("only monitoring data drift, missing concept drift")
    if not system.rollback_tested:
        findings.append("rollback path exists but has never been tested")
    if system.governance_rigor == "uniform":
        findings.append("governance not calibrated to actual model stakes")
    return findings or ["passes pre-deployment checklist"]
